/* Tentacle Pad pictures (owner's art, 5 looks LV1..LV5), cut to the machine and shrunk to 320 px wide (~23 KB each).
   Kept inside a .js file (not loose .webp files) so the game still opens by double-clicking index.html:
   a picture file loaded from disk cannot be used by the 3D drawing in Chrome, a picture written in the code can. */
(function (TBS) {
  'use strict';
  TBS.Art = TBS.Art || {};
  TBS.Art.pad = { w: 320, h: 278, looks: [
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,'
  ] };
})(window.TBS = window.TBS || {});
